 [MenuItem("ROM/Enemies/Build Rift bestiary and field UI")]public static void Build(){definitions.Clear();var folders=new[]{"Archmage","Destroyer","DeathKnight","King","Voidheart"};var ids=new[]{"broken-ember-oracle","ash-chainbreaker","eclipse-sworn","hollow-regent","fractured-heart-herald"};var names=new[]{"Oráculo de la Brasa Rota","Quebrantacadenas de Ceniza","Juramentado del Eclipse","Regente de la Corona Hueca","Heraldo del Corazón Fracturado"};var skills=new[]{RiftEnemySkill.EmberBolt,RiftEnemySkill.Cleave,RiftEnemySkill.Drain,RiftEnemySkill.Slam,RiftEnemySkill.VoidNova};for(int i=0;i<5;i++){string package="Assets/SculptiqStudios/InfernalSkeletons/"+folders[i];Create(ids[i],names[i],package,package+"/Prefabs/Infernal"+folders[i]+".prefab",false,i==3?2.3f:1.9f,skills[i]);}
