 for(int i=0;i<7;i++){string zoneName="Fauna - "+animalNames[i];var existing=world.transform.Find(zoneName);var go=existing?existing.gameObject:new GameObject(zoneName);go.transform.SetParent(world.transform,true);var zone=go.GetComponent<RiftEnemySpawnZone>()??go.AddComponent<RiftEnemySpawnZone>();var encounter=world.Encounters.Where(e=>e&&!e.MiniBoss&&e.SpawnPoints.Length>0).ElementAt(i%world.Encounters.Count(e=>e&&!e.MiniBoss&&e.SpawnPoints.Length>0));var points=new List<Transform>();for(int j=0;j<2;j++){string name="Wander point "+j;var child=go.transform.Find(name);if(!child){child=new GameObject(name).transform;child.SetParent(go.transform);}var origin=encounter.SpawnPoints[j%encounter.SpawnPoints.Length].position+new Vector3(8+j*5,0,8);if(NavMesh.SamplePosition(origin,out var nav,25,NavMesh.AllAreas))child.position=nav.position;else child.position=encounter.SpawnPoints[j%encounter.SpawnPoints.Length].position;points.Add(child);}var savedPoints=points.Select(pt=>pt.position).ToArray();go.transform.position=savedPoints[0];for(int n=0;n<points.Count;n++)points[n].position=savedPoints[n];zone.Title=animalNames[i];zone.SpawnPoints=points.ToArray();zone.Enemies=new[]{new RiftEnemySpawnChoice{Enemy=definitions[i+5],Weight=1}};zones.Add(zone);EditorUtility.SetDirty(zone);}population.Zones=zones.ToArray();EditorUtility.SetDirty(population);if(!UnityEngine.Object.FindFirstObjectByType<RiftFieldUI>(FindObjectsInactive.Include))PrefabUtility.InstantiatePrefab(uiPrefab);}
